def process(cnv_high_endometroid, hyperactivated_data):
    merged = cnv_high_endometroid.merge(hyperactivated_data, left_on='idx', right_on='sample_id')
    return merged[['protein']].drop_duplicates()

def process(hyperactivated_in_cnv_high, fda_targeted_genes):
    result = hyperactivated_in_cnv_high.merge(fda_targeted_genes, left_on='protein', right_on='gene_name')
    return result[['protein']].drop_duplicates().sort_values('protein')
